insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7aa7c045-3cd0-4ffe-aa02-400edd9bc5b7', 'ja', '好奇心を引くひと言は、なぜ直接的な質問よりも相手を引き込むのですか？', '["情報のすき間を埋めようとする、脳の働きを引き起こすから", "すぐに、事実としての答えを与えるから", "次に何が来るのか、知りたくさせるから"]'::jsonb, '好奇心は、もともとの無関心よりも強い、心理的な引力を生みます。')
