insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('588b3d53-613d-4e21-bdeb-77f6157427c7', 'ja', 'なぜ、下心ではなく好奇心で声をかけるべきなのですか？', '["好奇心のほうが控えめで、下心のほうが自信があるから", "好奇心は惹かれる気持ちを避け、下心は惹かれる気持ちを生むから", "好奇心は彼女がどんな人かを知ろうとし、下心は結果を求めるから"]'::jsonb, '好奇心は、その人を知ろうとします。下心は、結果を引き出そうとします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4003461a-b8aa-4eaa-b66f-3d5847986f38', 'ja', '彼女のノートパソコンに、アイスランドのステッカーが貼ってあるのに気づきます。純粋な好奇心が伝わるひと言は、どれですか？', '["「こんにちは。かわいいなと思って、話してみたくなりました」", "「コーヒーをおごらせてもらえますか？」", "「よく旅行をしていそうですね」", "「それ、アイスランドのステッカーですか？ちょうど去年行ったんです」"]'::jsonb, '彼女の経験への好奇心は、下心なしに、本物のつながりを招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d398047f-31f2-46cb-991f-abb7e05f231d', 'ja', '好奇心で声をかけると、なぜ下心で声をかけるよりも強い絆が生まれるのですか？', '["彼女を、達成すべき目標として扱うから", "彼女に、自分は面白い存在で、ちゃんと見てもらえていると感じさせるから", "結果を引き出そうとするプレッシャーがなくなるから", "より無理のない、本物の会話ができるから"]'::jsonb, '好奇心は、一人の人間としての彼女に目を向け、自然なつながりを育てます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7265d45c-cbbc-4d5e-8220-2d1c5fe793f2', 'ja', 'たまにしか声をかけないと、なぜ難しく感じるのですか？', '["一回の重みが大きく感じられるから", "成功の可能性が下がるから", "タイミングが悪くなるから", "恐れが大きくなるから"]'::jsonb, '声をかけることがまれだと、一回一回の重みが増し、より強烈に感じられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('31e5395b-0177-4703-8182-44c9921a16fc', 'ja', '本来できるはずの回数より声をかける回数が少なくなるのは、どんな間違いが原因ですか？', '["良くない場所にいること", "理想的な条件を待つこと", "スマホを見ていること", "関心がないこと"]'::jsonb, '完璧な条件を待っていると、チャンスの総数が減ります。声は、いつでもかけられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b04aa8-e3ca-474a-af0c-4aac0238c9b5', 'ja', '人と関わる機会を保ち続ける習慣は、どれですか？', '["ふだんの一日の中で、知らない人に話しかけること", "どんな場所も、つながりを練習する場として扱うこと", "完全に自信があるときだけ、声をかけること"]'::jsonb, '日ごろから人と関わっていると、プレッシャーが下がり、やり取りが楽に感じられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5cd29e03-754c-4a91-8b5a-132fe680704d', 'ja', '3秒ルールの目的は、何ですか？', '["緊急性を生むこと", "断られるのを避けること", "最初のひと言を完璧にすること", "抵抗が大きくなる前に動くこと"]'::jsonb, 'すばやく動けば、迷いがふくらむのを止められます。彼女に気づいてから3秒以内に動きましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('71a2b057-c0c3-49ae-a552-62426201f6c9', 'ja', '待つと、なぜ声をかけるのが難しくなるのですか？', '["恐れがふくらむから", "エネルギーが下がるから", "関心が薄れるから", "注意が移るから"]'::jsonb, '心に結果を想像する時間があると、恐れは大きくなります。すばやく動きましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8119be9-b1ef-4a0d-ab94-b3b7fdcf7ef2', 'ja', 'バーで魅力的な女性を見かけ、声をかけたいと思います。どうするべきですか？', '["完璧な最初のひと言を考え始める", "まず、断られるリスクについて考える", "3秒以内に、彼女のほうへ動く", "恐れがなくなるまで、じっとしている"]'::jsonb, '分析が抵抗とためらいを生む前に、動きましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50b60dd8-f15e-4fdb-bbb1-8651ce23d2c0', 'ja', '彼女の通り道や動きをふさぐと、なぜ不快感を生むのですか？', '["脅威に対する反応を、自動的に引き起こすから", "失礼に感じられるから", "支配力を示すから"]'::jsonb, '体は、意識して考えるより先に、動ける範囲を狭められたことに反応します。彼女にスペースを残しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('eddec612-c258-4098-80cf-80aed2555258', 'ja', '声をかけてから、彼女が動きにくい状態だと気づきます。一番良い調整はどれですか？', '["一歩下がって、スペースを空ける", "もっと速く話す", "彼女を褒める"]'::jsonb, 'スペースを残すことで、相手の神経系はリラックスし、受け入れやすい状態に保たれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('aea4811b-264d-435b-ab0a-4bcab3bc274a', 'ja', '心地よい声のかけ方につながる選択は、どれですか？', '["見える位置にいること", "出口をふさぐこと", "近づきすぎること", "動けるスペースを残すこと"]'::jsonb, '見える位置にいることと、スペースを残すことで、相手の神経系はリラックスし、受け入れやすい状態に保たれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2e5b5d64-e126-4877-9449-ad662c2d047e', 'ja', 'リラックスした体の動きは、話す前に何を伝えますか？', '["自信、心地よさ、そして脅威ではないという意図", "申し訳なさそうな、または威圧的な存在感", "すぐに承認が欲しいという気持ち", "周りの環境への無関心"]'::jsonb, 'なめらかで開いた動きは、無意識のうちに、良いスタートの土台をつくります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e26bd7a-b3cd-4d6e-af6b-4122066f80b5', 'ja', 'ぎくしゃくした、ためらいがちな足取りで彼女のほうへ歩いています。一番良い動きはどれですか？', '["近づく前に、ペースを落とし、肩の力を抜き、自分を落ち着かせる", "その場で立ち止まり、代わりに彼女に呼びかける", "自分らしさと正直さを示すために、今の動きを続ける"]'::jsonb, 'リラックスした動きは安全を伝え、彼女にとってやり取りを楽なものにします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bdb5e4d4-24f8-4710-a0ac-91194b2f10a8', 'ja', '近づくときに不快感を減らす動きは、どれですか？', '["安定したペース", "さりげなく目を向けること", "こわばった肩", "まっすぐな姿勢"]'::jsonb, 'リラックスした動きは安全を伝え、彼女にとってやり取りを楽なものにします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7bc72d1b-23c3-4183-b696-a4c0d69085b0', 'ja', '声をかける前に、目を合わせて小さくほほえむことは、なぜ役立つのですか？', '["友好的な意図を伝え、安全かどうかを見きわめる時間を彼女に与えるから", "まだ話してもいないうちに、惹かれる気持ちを築くから", "期待感を生み、彼女の気持ちをより引き込むから"]'::jsonb, '小さな笑顔は親しみを伝え、アイコンタクトは、彼女が落ち着いてこちらを認識する助けになります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48a8252e-7d72-4d16-ac74-c694f14bde94', 'ja', '部屋の向こう側から目が合います。彼女はすぐに目をそらします。一番良い対応はどれですか？', '["それでも声をかける。すぐに目をそらすのは、多くの場合、反射的なもので、拒絶ではない", "関心を確かめるために、彼女がもう一度こちらを見るのを待ってから声をかける", "はっきり関心がないと示されたので、声をかけるのをやめる"]'::jsonb, 'すぐに目をそらすのは、多くの場合、反射的なもので、意識的な拒絶ではありません。それでも声をかけましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('42ba6d8b-fdaa-43b8-8fda-ad92c655df6e', 'ja', '早い段階の温かいアイコンタクトは、なぜ第一印象を良くするのですか？', '["不意を突いて、より強い印象を与えるから", "安全かどうかを、前もって見きわめる時間を与えるから", "身構えさせる原因になる、驚きを防ぐから", "そばに行く前に、友好的な意図を伝えるから"]'::jsonb, '見えていることと温かさが、声をかけられることを、唐突ではなく安全なものに感じさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9cbb1c37-1c29-4754-8d5f-f95600cf8b0a', 'ja', 'さりげないひと言は、なぜ声をかけられる彼女のプレッシャーを減らすのですか？', '["ふつうの会話のように感じられるから", "惹かれる気持ちを避けるから", "彼女がこちらに惹かれやすくなるから"]'::jsonb, 'さりげないひと言は、ありふれていて自然に感じられるので、二人ともプレッシャーが下がります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d2e1560-b720-4464-8836-db55cf007d4a', 'ja', 'カフェで彼女の隣の席に座っています。使えるさりげないひと言は、どれですか？', '["ここに来たことがあるか、何がおすすめかを聞く", "見た目を褒める", "恋人がいるかどうかを聞く"]'::jsonb, 'さりげないひと言は、ありふれていて自然に感じられるので、二人ともプレッシャーが下がります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5033dee2-a2a9-45d9-b214-0035a1ff5a9f', 'ja', '二人とも、遅れている電車を待っています。さりげないひと言になるのは、どれですか？', '["彼女が身につけているものを褒める", "電車がいつ来るか知っているかを聞く", "自己紹介をして、名前を聞く", "遅れについてひと言言う"]'::jsonb, '同じ状況を共有していると、話しかけられることが自然に感じられ、応じやすくなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('73629f15-ce28-4413-a2af-85b0b03c1ef2', 'ja', '意図を伝えるストレートなひと言とは、何ですか？', '["心地よさを確かめるために、軽い会話から始めること", "打ち解けるために、当たり障りのない雑談を使うこと", "惹かれていることや恋愛的な意図を、最初にはっきり伝えること"]'::jsonb, 'ストレートなひと言は、最初に意図を伝えることで、あいまいさを取り除きます。彼女には、なぜ声をかけられたのかが分かります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('adb1f5a5-29e7-4c3b-88a1-33da91269c81', 'ja', 'バーで彼女を見かけ、早くはっきりさせたいと思います。一番良い最初のひと言はどれですか？', '["店についてひと言言う", "ここにはよく来るのかを聞く", "人の多さについて冗談を言う", "話してみたかったと伝える"]'::jsonb, 'ストレートに伝えることで、探り合いがなくなり、すぐに意図が伝わります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b6195146-f317-46e7-b387-626cd480fe2b', 'ja', 'クラブで、音楽が大音量で流れています。ここでストレートなひと言がうまくいくのは、何があるときですか？', '["許可を求めない、落ち着いた自信のある伝え方", "彼女と友人たちの邪魔をしたことを謝ること", "安定したアイコンタクトと、リラックスしたボディランゲージ"]'::jsonb, 'ストレートなひと言は、自信ではなく謝罪とともに伝えると、力を失います。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('587818de-4443-410a-b2e6-4b7c30881359', 'ja', '「空気をリードする」とは、何ですか？', '["惹かれているサインを管理すること", "話題、ペース、エネルギーを導くこと", "彼女の気分に合わせること", "断られるのを避けること"]'::jsonb, '空気をリードするとは、その場に反応するのではなく、その場を導くことです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6f2f6f50-a54c-4103-af26-fc4b7d7eb5a0', 'ja', '本を読んでいる彼女に声をかけます。割り込みではなく、「ここにいて当然」という姿勢が伝わるひと言は、どれですか？', '["「お邪魔してすみません。何を読んでいるんですか？」", "「その本、面白いですか？読もうかなと思っていたんです」", "「ご迷惑でなければいいんですが、どうしてもひと言ごあいさつしたくて」"]'::jsonb, '場の空気をしっかりつくれるのは、許可ではなく自信です。謝らずに話しかけましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90f24790-0a2d-429f-8aff-e70a5e1589ec', 'ja', '最初のひと言を、彼女がそれまでしていたことよりも面白くするものは何ですか？', '["今の環境よりも、声が大きく、大胆で、エネルギーが高いこと", "好奇心、遊び心、大切にされている感覚といった、感情の引っかかりをつくること", "観察にもとづいて、彼女が夢中になっている話題に触れること"]'::jsonb, '場の空気を魅力的にするのは、遊び心や好奇心といった感情の引っかかりです。声の大きさではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2ecc4789-34ea-4c3f-a98b-9f7ded7e80ca', 'ja', '声の大きさを環境に合わせることは、なぜ大切なのですか？', '["叫ぶのを避けるため", "言い直しを防ぐため", "やり取りの引っかかりを減らすため", "魅力的に聞こえるため"]'::jsonb, '声の大きさが合っていないと、引っかかりが生まれます。環境に合わせて、やり取りを楽に保ちましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e12bb639-9fd1-465e-9e08-5cdeb7ccd65f', 'ja', '最初のひと言のあと、彼女が身を乗り出して「え？」と聞き返します。一番良い動きはどれですか？', '["同じ言葉を、同じ音量で繰り返す", "言い終えるために、もっと速く話す", "彼女のスペースに、さらに近づく", "音量を調整して、落ち着いて繰り返す"]'::jsonb, '音量を環境に合わせましょう。内容よりも、合わせることのほうが大切です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e173f101-7036-4046-854b-556473b41c8b', 'ja', '声の使い方で、引っかかりを生むものは何ですか？', '["その環境では、はっきり聞こえないほど小さな声で話すこと", "低く、よく響くトーンで話すこと", "息をつかずに、言葉を急いで言うこと", "言葉の発音がはっきりしないこと"]'::jsonb, '引っかかりは、環境に合っていないことから生まれます。音量を調整し、息をして、はっきり話しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3a6aa99-3aa6-471c-b81a-ea31d016cfb1', 'ja', 'やり取りに本当に心を開いていることを表す行動は、どれですか？', '["ほほえむこと", "どちらともつかないトーン", "質問を返してくること", "こちらの質問に答えること"]'::jsonb, '質問は、ただの礼儀ではなく、会話に加わっているサインです。続けていい青信号として受け取りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('100aee65-eee7-4907-899a-20d6b97820b1', 'ja', '早い段階でサインを読み取ることの、主な目的は何ですか？', '["より早く距離を縮めるため", "断られるのを避けるため", "敬意を保つため", "彼女を感心させるため"]'::jsonb, '彼女の心地よさが最優先です。続けるか、引くかを決めるために、サインを使いましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9745631b-e02b-44c5-8703-7cfda0ab734f', 'ja', '受け入れではなく、たいてい礼儀を示している手がかりは、どれですか？', '["短い笑顔", "短い、最小限の返事", "質問が返ってこないこと", "していたことの手を止めること"]'::jsonb, '礼儀は、続きを招くことなく、その場の和を保ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a1716c8d-11f9-4afa-b80c-5a108dce463e', 'ja', '彼女にどれくらい関心があるのか分からないとき、次の一手として一番良いのは何ですか？', '["彼女が打ち解けてくるまで、会話を続ける", "「はい」も「いいえ」も言いやすい、はっきりした一歩を踏み出す", "安心してもらうために、質問をいくつも重ねる", "彼女のほうから距離を縮めてくるのを待つ"]'::jsonb, 'はっきりしたひと言は、その礼儀正しさが関心なのか、ただの礼儀なのかを明らかにして、あいまいさを取り除きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab5203db-096d-46a0-b56b-1b2011ec738e', 'ja', 'やり取りの中で、関心を確かめるために、はっきりした一歩を一度だけ踏み出す目的は何ですか？', '["あいまいさを取り除き、彼女に断りやすい逃げ道を渡すため", "関心を持つように、彼女を説得するため", "彼女の反応に関係なく、やり取りを早く進めるため"]'::jsonb, 'はっきりしたひと言は、その礼儀正しさが関心なのか、ただの礼儀なのかを明らかにして、あいまいさを取り除きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('450abadf-8d1e-486e-b76f-6d6eb4d366a0', 'ja', 'どちらともつかないサインのあと、関心をはっきりさせるのに役立つひと言は、どれですか？', '["「今度、コーヒーでもどうですか？」", "「それで、お仕事は何をしているんですか？」", "「そろそろ失礼しますね。LINEを交換しませんか？」", "「何を考えているのか、ちょっと読めない人ですね」"]'::jsonb, 'はっきりしたひと言は、その礼儀正しさが関心なのか、ただの礼儀なのかを明らかにして、あいまいさを取り除きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5b86928-0a71-456d-a08d-f5aaaa20bce3', 'ja', '受け入れのサインには、たいていどんなものが含まれますか？', '["こちらに向けた体と、本物の笑顔", "質問を返してくることと、続く関わり", "短い返事と、目をそらすこと", "身を乗り出すこと、または同じだけ返ってくるエネルギー"]'::jsonb, '受け入れている女性は、最初から、開いていて、気持ちの入った行動を見せます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3401c3d2-b41a-4191-b69d-0ad4a8292b16', 'ja', 'サインを正しく読み取ることが役立つのは、なぜですか？', '["やり取りを心地よく保つから", "プレッシャーを防ぐから", "彼女が、より恋の駆け引きに乗ってくるから", "惹かれる気持ちを保証するから"]'::jsonb, '相手の反応を見て合わせることが守るのは、結果ではなく、心地よさです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e069eb31-5232-4ac9-b7e0-bd4b26b8bd92', 'ja', '彼女は短く答え、すぐに視線を元に戻し、体はこちらからそむけています。これはどのサインですか？', '["受け入れのサイン。彼女は恥ずかしがっていて、温かく粘ってもらう必要がある", "礼儀のサイン。まだ分からないので、もう一度だけ試してから見きわめる", "冷たいサイン。関心が離れているので、それ以上押さずに、すっきりと切り上げる"]'::jsonb, '閉じたボディランゲージは、返事よりも重みがあります。一歩引いて、落ち着いて立ち去りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0251b9d5-9ecf-4f71-aad2-dfc93f31e392', 'ja', '最初のひと言を、引き込まれるものにする要素は、どれですか？', '["プレッシャー", "好奇心", "遊び心", "ミステリアスさ"]'::jsonb, '場の空気は、何かを求めるものではなく、興味をそそるものに感じられるとき、一番うまく働きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('02e3aec0-93e1-49e3-8801-5e138b373f07', 'ja', '優れたさりげないひと言は、なぜ効果的なのですか？', '["惹かれていることを、はっきり伝えるから", "周りの環境や、目に入ったものについて触れるから", "彼女の見た目だけに注目するから", "早い段階で、約束を求めるから"]'::jsonb, '同じ状況を共有していることが、安心感と自然な流れを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0601d6e9-3b2f-4dab-8c82-816f101403cc', 'ja', 'やり取りを続けて深めていいと伝えるサインは、どれですか？', '["こちらに体を向け、質問をし、開いたボディランゲージを保っている", "ほほえみ、長く答え、同じだけ返してくれる", "どちらも受け入れのサインを示している"]'::jsonb, 'どれも受け入れのサインです。そのまま続けて、深めていきましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('06c68907-301c-447a-b17d-47f93da821ac', 'ja', 'ストレートに声をかけて、すぐに相手を「見きわめモード」にすることの強みは、何ですか？', '["女性は、意図を隠さない男性に敬意を持つ", "自信のあるストレートさが、最初の惹かれるきっかけを生む", "彼女に関心があれば、打ち解けるまでの「建前のやり取り」を飛ばせる"]'::jsonb, 'すでに関心があるなら、ストレートなひと言は前置きを省き、進展を早めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('073d5930-369f-4dd9-9245-c250f26097bc', 'ja', '礼儀正しさは、なぜ受け入れられていると誤解されやすいのですか？', '["親しげに聞こえるから", "居心地の悪さを隠すから", "そっけないから", "断るのを先延ばしにするから"]'::jsonb, '礼儀正しい返事は、関心が離れていることを隠す場合があります。同じだけ返ってくるかどうかを見ましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('08850c3a-5d7f-4d3c-923c-731d1e3f4644', 'ja', '彼女は笑顔で「うん」と言いますが、こちらが話しているあいだ、ずっと店内を見回しています。どう判断しますか？', '["受け入れのサイン。笑顔は関心を意味する", "礼儀のサイン。丁寧だが、気持ちはここにない", "入り混じったサイン。気は散っているが、興味はある", "冷たいサイン。見回すのは、いつでも拒絶を意味する"]'::jsonb, '注意が分散しているのは、関わっているサインではなく、礼儀のサインです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0a2112a8-7aa5-4d33-8a7d-8b46d381ad1c', 'ja', '彼女は温かく答えてくれますが、何度もスマホを確認します。これはおそらく、どういう意味ですか？', '["緊張している", "こちらを試している", "忙しいか、関心が離れつつある", "粘ってほしいと思っている"]'::jsonb, '関わるには、集中が必要です。それがないときは、先へ押し進めてはいけません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b567d7e-67fa-4529-a5cb-2a646b501ae0', 'ja', '彼女はバーで友人たちと一緒にいます。グループへの最初のひと言がうまくいくかどうかを決めるものは、何ですか？', '["そのひと言が面白く、みんなの意見を巻き込むものであること", "質問するときの、自信のある伝え方", "質問からふつうの会話へ、どう移るか"]'::jsonb, '最初のひと言は、面白く、グループ全体が加わる必要のあるものにしましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0d78b9e6-8caf-46a0-9c29-39a256ccdd34', 'ja', 'ストレートに伝えることは、実際には何をもたらしますか？', '["魅力的な資質を示す", "正直さを通じて、惹かれる気持ちを生む", "彼女が、こちらの意図を読み解かなくて済む", "別の理由でそこにいるふりを、しなくて済む"]'::jsonb, 'ストレートなひと言は、最初に意図を伝えることで、あいまいさを取り除きます。彼女には、なぜ声をかけられたのかが分かります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0dca33cf-d79b-4b24-88c0-4b19d5c03b2c', 'ja', '二人ともドッグランにいて、犬たちが遊ぶのを見ています。プレッシャーを減らす最初のひと言は、どれですか？', '["「かわいい犬ですね。飼い主さんに似て」", "「LINEを交換しませんか？」", "「犬のほうが、人間よりいいですよね」", "「何という犬種ですか？うちの子は、いつも元気がありすぎて」"]'::jsonb, 'その場で共有している体験が、会話を自然に始めさせてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0e096470-35cf-4e08-bf03-85d6267ab373', 'ja', '後悔の痛みは、なぜ断られた痛みより長く続くのですか？', '["脳は、一瞬の「断られた」よりも、逃したチャンスを長く再生するから", "断られれば区切りがつくが、後悔は答えのない問いをいつまでも残すから", "上の両方"]'::jsonb, '断られれば区切りがつきます。一方、後悔は、起きなかったことを心に再生させ続けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0f4f3084-9f90-4036-ae95-cc8c706eba49', 'ja', '意見を尋ねることは、なぜ雑談よりも相手を引き込むのですか？', '["意見には、より長い答えが必要だから", "意見のほうが、知的に感じられるから", "意見を聞くことは、彼女の判断が大切にされていると伝えるから", "意見のほうが、褒め言葉より安全に感じられるから"]'::jsonb, '人は、自分の視点が大切にされると、ぱっと明るくなります。大切にされることが、関わりを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10284be9-9647-41db-8f18-3dfa77d66507', 'ja', '近づいているあいだ、視線はどこに向けるべきですか？', '["さりげなく短く目を合わせる。じっと見つめたり、視線を固定したりしない", "はっきりした意図と関心を示すために、彼女を見据えたままにする", "強すぎる印象を避けるために、彼女の少し向こうを見る"]'::jsonb, '短いアイコンタクトは、プレッシャーを与えずに、こちらが気づいていることを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14546a1d-9532-4604-b285-8494197100dd', 'ja', '近づく角度と距離に気を配る目的は、何ですか？', '["心地よさを妨げる、不要な壁を取り除く", "近さによって、最大限の自信を示す", "彼女に、少し脅威を感じさせる", "すぐに惹かれる気持ちが生まれることを保証する"]'::jsonb, '敬意のある近づき方なら、彼女は不快感に対処することなく、やり取りに応じられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14dc2ce1-631c-4b7a-b151-4c74c34bb2a3', 'ja', 'クラブで、フロアの向こう側にいる彼女と目が合います。彼女がほほえみます。どう動きますか？', '["ほほえみ返して、彼女のほうから来るか様子を見る", "すぐに彼女のほうへ動く", "目を合わせ続ける", "声をかけやすい位置に彼女が来るまで待つ"]'::jsonb, 'クラブでは、決断の速さが報われます。きっかけが開いたら、すぐに踏み出しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('152af858-f915-4ba0-97af-dcd17bde6c3a', 'ja', 'サインを読み取ることは、なぜ彼女の心地よさのために大切なのですか？', '["彼女がまだ開いていない境界線を、越えて押し進めずに済むから", "彼女のサインを尊重することが、相手に合わせられる人だと示すから", "礼儀のサインや冷たいサインを無視して続けると、彼女を不快にさせるから", "上のすべて"]'::jsonb, 'サインは、何が歓迎されているかを示します。まだ開かれていない境界線を越えないように、サインに従いましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('16844e95-a04f-4bcf-a8af-c185f70db3c7', 'ja', 'ストレートなひと言を台無しにする伝え方は、どれですか？', '["落ち着いたトーン", "アイコンタクト", "自信のあるエネルギー", "申し訳なさそうなエネルギー"]'::jsonb, 'ストレートなひと言は、自信ではなく謝罪とともに伝えると、力を失います。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('170329e0-190e-459a-8870-3da632ce2a7f', 'ja', '好奇心から声をかけていることを示す行動は、どれですか？', '["細かいところに気づき、それについて尋ねること", "先のことを考えずに、会話を楽しむこと", "連絡先を聞く方向へ、すぐに話を持っていくこと", "方向を無理に決めず、やり取りの展開に任せること"]'::jsonb, '好奇心は、今この瞬間にとどまり、知ろうとし続けます。下心は、結果へと先走ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('18168e30-017b-49fc-8902-92152cce90b8', 'ja', '騒がしいナイトクラブで、彼女がこちらを一瞬見てから、向き直ります。どうするべきですか？', '["関心があるという、もっとはっきりしたサインを待つ", "良いエネルギーと笑顔で声をかける", "彼女のグループの邪魔をしないように、小さな声で話す", "あきらめて、ほかの人を探す"]'::jsonb, '夜の店では、注意が移る前の、すばやく自信のある行動が報われます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
